def operation(n):
    if n < 0:
        raise ValueError("Input must be non-negative")
    d = n % 10
    r = n // 10
    return r + 3 * d

def find_cycle(start_n, max_steps=100):
    sequence = []
    visited = {}  # Map value to step index when first seen
    current = start_n
    step = 0

    while current not in visited and step < max_steps:
        visited[current] = step
        sequence.append(current)
        current = operation(current)
        step += 1

    if current in visited:
        start_index = visited[current]
        cycle_start_index = start_index
        cycle_length = step - start_index
        transient_path = sequence[:start_index]
        cycle = sequence[start_index:]
        return transient_path, cycle, cycle_length
    else:
        # Should not happen if max_steps is large enough for small numbers
        return sequence, [], 0

# Analyze N from 10 to 120
results = {}
for n in range(10, 121):
    transient, cycle, length = find_cycle(n)
    results[n] = {'transient': transient, 'cycle': cycle, 'length': length}

# Print summary of cycles found and mapping
cycles_map = {}
for n, data in results.items():
    if data['cycle']:
        cycle_tuple = tuple(data['cycle'])
        if cycle_tuple not in cycles_map:
            cycles_map[cycle_tuple] = []
        cycles_map[cycle_tuple].append(n)

print("--- Cycles Found ---")
for cycle, starters in cycles_map.items():
    print(f"Cycle: {cycle} (Length: {len(cycle)})")
    print(f"  Leads from starters: {sorted(starters)}")

print("\n--- Fixed Points Check (Length 1) ---")
